from collections import namedtuple
from itertools import chain


Par = namedtuple("Par", ["bottom", "delta"])


def parse(s) -> Par:
    bottom = 0
    delta = 0
    for c in s:
        delta += 1 if c == "(" else -1
        bottom = min(bottom, delta)
    return Par(bottom=bottom, delta=delta)


def compute(pars):
    h = 0
    for par in pars:
        if h + par.bottom < 0:
            return None
        h += par.delta
    return h


def main():
    N = int(input())

    incs = []
    decs = []
    for _ in range(N):
        par = parse(input())
        if par.delta > 0:
            incs.append(par)
        else:
            # look from right side
            # i.e. move origin to delta
            decs.append(Par(bottom=par.bottom-par.delta, delta=-par.delta))
    # sort by bottom in descending order
    incs.sort(key=lambda p: p.bottom, reverse=True)
    decs.sort(key=lambda p: p.bottom, reverse=True)

    inc_tot = compute(incs)
    dec_tot = compute(decs)
    if inc_tot and dec_tot and inc_tot == dec_tot:
        print("Yes")
    else:
        print("No")


if __name__ == '__main__':
    main()

